#include "pfodClock.h"

/*
 * Default millis() and yield(). Both are weak, so defining your own (non-weak)
 * version in any .cpp file of your program replaces the default here at link
 * time. Do not edit this file to port to your micro.
 *
 * micros() is NOT defined in the library. Your program must supply it, e.g. in
 * target_pfodClock.cpp alongside main.cpp, using your board's timer.
 */

/**
 * Default milliseconds since startup, derived from micros().
 * Adds the micros() elapsed since the previous call to a running uS remainder
 * and moves whole milliseconds into the ms count. Using (now - lastMicros)
 * gives the correct elapsed time across a micros() wrap, so millis() keeps
 * counting correctly. Must be called at least once per micros() wrap period.
 * Weak, so defining your own millis() in any .cpp file of your program
 * replaces this one. Normally you only supply micros().
 * @return the current millisecond count
 */
unsigned long __attribute__((weak)) millis() {
  static unsigned long lastMicros = 0;   // micros() at the previous call
  static unsigned long msCount = 0;      // accumulated milliseconds
  static unsigned long uSRemainder = 0;  // accumulated uS not yet counted as a whole ms
  unsigned long now = micros();
  uSRemainder += (now - lastMicros);
  lastMicros = now;
  msCount += uSRemainder / 1000;
  uSRemainder = uSRemainder % 1000;
  return msCount;
}

/**
 * Default yield(), does nothing.
 * Weak, so defining your own yield() anywhere in your program replaces this one.
 */
void __attribute__((weak)) yield() {
}
